    questions: [
      { topic: "Số có nhiều chữ số", type: "mc", q: "Số 2 050 300 đọc là:", o: ["Hai triệu không trăm năm mươi nghìn ba trăm", "Hai triệu năm trăm nghìn ba trăm", "Hai trăm linh năm nghìn ba trăm", "Hai triệu không trăm năm mươi nghìn không trăm ba mươi"], x: "Tách lớp: 2 | 050 | 300. Đọc: hai triệu, không trăm năm mươi nghìn, ba trăm.", lv: 1 },
      { topic: "Số có nhiều chữ số", type: "fill", q: "Giá trị của chữ số 8 trong số 3 816 405 là ___", ans: ["800 000", "800 nghìn", "8 trăm nghìn", "tám trăm nghìn"], x: "Tách lớp: 3 | 816 | 405. Chữ số 8 ở hàng trăm nghìn nên có giá trị 800 000.", lv: 1 },
      { topic: "Số có nhiều chữ số", type: "mc", q: "Lớp nghìn của số 52 714 096 gồm các chữ số:", o: ["7; 1; 4", "5; 2", "0; 9; 6", "2; 7; 1"], x: "Tách lớp từ phải sang trái: 52 | 714 | 096. Lớp nghìn gồm 7, 1, 4.", lv: 1 },
      { topic: "Số có nhiều chữ số", type: "tf", q: "987 654 > 1 000 000", a: false, x: "987 654 có 6 chữ số, 1 000 000 có 7 chữ số. Số nào nhiều chữ số hơn thì lớn hơn, nên 987 654 < 1 000 000.", lv: 1 },
      { topic: "Làm tròn số", type: "fill", q: "Làm tròn số 7 249 860 đến hàng trăm nghìn, ta được ___", ans: ["7 200 000"], x: "Xét chữ số hàng chục nghìn: là 4, bé hơn 5 nên làm tròn xuống. Làm tròn số 7 249 860 đến hàng trăm nghìn ta được 7 200 000.", lv: 1 },
      { topic: "Số chẵn, số lẻ", type: "fill", q: "Số chẵn lớn nhất có năm chữ số là ___", ans: ["99 998"], x: "Số lớn nhất có năm chữ số là 99 999 (số lẻ). Số chẵn liền trước nó là 99 998.", lv: 2 },
      { topic: "Số có nhiều chữ số", type: "mc", q: "Có bao nhiêu số tự nhiên bé hơn 5?", o: ["5", "4", "6", "3"], x: "Các số tự nhiên bé hơn 5 là 0, 1, 2, 3, 4 (số 0 cũng là số tự nhiên). Có 5 số.", lv: 1 },
      { topic: "Biểu thức chứa chữ", type: "fill", q: "Với m = 7 và n = 9, giá trị của biểu thức (m + n) × 7 là ___", ans: ["112"], x: "Thay m = 7, n = 9: (7 + 9) × 7 = 16 × 7 = 112. Tính trong ngoặc trước.", lv: 1 },
      { topic: "Biểu thức chứa chữ", type: "mc", q: "Với b = 5, biểu thức nào có giá trị lớn nhất?", o: ["200 − b", "b × 30", "b + 120", "600 : b"], x: "Thay b = 5: 200 − 5 = 195; 5 × 30 = 150; 5 + 120 = 125; 600 : 5 = 120. Lớn nhất là 195.", lv: 2 },
      { topic: "Phép cộng, phép trừ", type: "fill", q: "386 405 + 572 718 = ___", ans: ["959 123"], x: "Đặt tính rồi cộng từ phải sang trái, nhớ sang hàng bên trái: 386 405 + 572 718 = 959 123.", lv: 1 },
      { topic: "Phép cộng, phép trừ", type: "fill", q: "657 928 − 219 635 = ___", ans: ["438 293"], x: "Đặt tính rồi trừ từ phải sang trái, có nhớ ở hàng chục và hàng nghìn: 657 928 − 219 635 = 438 293. Thử lại: 438 293 + 219 635 = 657 928.", lv: 1 },
      { topic: "Phép cộng, phép trừ", type: "fill", q: "135 470 + ___ = 482 650", ans: ["347 180"], x: "Muốn tìm số hạng chưa biết, lấy tổng trừ số hạng đã biết: 482 650 − 135 470 = 347 180.", lv: 2 },
      { topic: "Tính chất phép cộng", type: "mc", q: "Tính bằng cách thuận tiện: 4 725 + 999 + 275 = ?", o: ["5 999", "5 899", "6 000", "5 989"], x: "Nhóm hai số có tổng tròn nghìn: (4 725 + 275) + 999 = 5 000 + 999 = 5 999.", lv: 2 },
      { topic: "Tổng và hiệu", type: "fill", q: "Tổng của hai số là số lớn nhất có ba chữ số, hiệu của chúng là 101. Số lớn là ___", ans: ["550"], x: "Số lớn nhất có ba chữ số là 999. Số lớn = (999 + 101) : 2 = 550. Số bé = 999 − 550 = 449.", lv: 3 },
      { topic: "Tổng và hiệu", type: "tf", q: "Hai số có tổng là 90 và hiệu là 14. Số bé là (90 + 14) : 2.", a: false, x: "(90 + 14) : 2 = 52 là số lớn. Số bé là (90 − 14) : 2 = 38. Thử lại: 52 + 38 = 90 và 52 − 38 = 14.", lv: 1 },
      { topic: "Giải bài toán có ba bước tính", type: "mc", q: "Mẹ mua 4 kg táo, mỗi ki-lô-gam giá 22 000 đồng, và một hộp sữa giá 21 000 đồng. Mẹ đưa cô bán hàng 150 000 đồng. Cô trả lại mẹ bao nhiêu tiền?", o: ["41 000 đồng", "109 000 đồng", "62 000 đồng", "107 000 đồng"], x: "Tiền táo: 22 000 × 4 = 88 000 (đồng). Tiền táo và sữa: 88 000 + 21 000 = 109 000 (đồng). Tiền trả lại: 150 000 − 109 000 = 41 000 (đồng).", lv: 3 },
      { topic: "Giải bài toán có ba bước tính", type: "fill", q: "Một kho có 12 850 kg gạo. Ngày thứ nhất xuất 3 200 kg, ngày thứ hai xuất gấp đôi ngày thứ nhất. Kho còn lại ___ kg gạo.", ans: ["3 250"], x: "Ngày thứ hai xuất: 3 200 × 2 = 6 400 (kg). Hai ngày xuất: 3 200 + 6 400 = 9 600 (kg). Còn lại: 12 850 − 9 600 = 3 250 (kg).", lv: 3 },
      { topic: "Góc và đo góc", type: "mc", q: "Một góc có số đo gấp 5 lần 20°. Góc đó là:", o: ["Góc tù", "Góc nhọn", "Góc vuông", "Góc bẹt"], x: "Số đo của góc là 20° × 5 = 100°. Góc 100° lớn hơn góc vuông (90°) và bé hơn góc bẹt nên là góc tù.", lv: 2 },
      { topic: "Đơn vị đo", type: "mc", q: "Chọn đơn vị đo thích hợp: Một chiếc xe máy nặng khoảng 1 …", o: ["tạ", "kg", "yến", "tấn"], x: "Một chiếc xe máy nặng gần bằng ba bạn học sinh lớp 4 cộng lại, tức là khoảng 1 tạ. Nặng 1 kg hay 1 yến thì quá nhẹ, còn 1 tấn thì nặng như một chiếc ô tô.", lv: 2 },
      { topic: "Góc và đo góc", type: "mc", q: "Thước đo góc dùng để đo góc theo đơn vị nào?", o: ["Độ (°)", "Xăng-ti-mét (cm)", "Mét vuông (m²)", "Giây"], x: "Đơn vị đo góc là độ, kí hiệu °. Ví dụ: góc vuông bằng 90°.", lv: 1 },
      { topic: "Đơn vị đo", type: "fill", q: "7 yến 6 kg = ___ kg", ans: ["76"], x: "1 yến = 10 kg nên 7 yến = 70 kg; 70 + 6 = 76 (kg).", lv: 2 },
      { topic: "Đơn vị đo", type: "fill", q: "5 dm² 8 cm² = ___ cm²", ans: ["508"], x: "1 dm² = 100 cm² nên 5 dm² = 500 cm²; 500 + 8 = 508 (cm²).", lv: 2 },
      { topic: "Đơn vị đo", type: "mc", q: "Năm 1945 thuộc thế kỉ nào?", o: ["Thế kỉ XX", "Thế kỉ XIX", "Thế kỉ XXI", "Thế kỉ XV"], x: "Thế kỉ XX tính từ năm 1901 đến hết năm 2000. Năm 1945 nằm trong khoảng đó.", lv: 2 },
      { topic: "Đường thẳng vuông góc, song song", type: "mc", q: "Hình chữ nhật ABCD có bao nhiêu cặp cạnh vuông góc với nhau?", o: ["4", "2", "1", "8"], x: "Hai cạnh chung một đỉnh của hình chữ nhật thì vuông góc: AB và BC, BC và CD, CD và DA, DA và AB. Có 4 cặp.", lv: 2 },
      { topic: "Hình bình hành, hình thoi", type: "tf", q: "Hình bình hành ABCD có AB = 7 cm, BC = 4 cm. Chu vi hình bình hành là 22 cm.", a: true, x: "Hình bình hành có các cạnh đối diện bằng nhau: CD = 7 cm, DA = 4 cm. Chu vi: 7 + 4 + 7 + 4 = 22 (cm).", lv: 2 }
    ]
